func (r *counterRepository) Insert(entity *Counter) fdblayer.Mutation {
	return fdblayer.MutationFunc(func(ctx context.Context, tx *fdblayer.Tx) (func(context.Context) error, error) {
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		tr := tx.Transaction()
		dir := tx.Dir()
		key := dir.Pack(tuple.Tuple{CounterTypeID, fdblayer.DataNamespace, entity.Id})
		if !tx.ClaimKey(key, "") {
			return nil, fmt.Errorf("counter %w", fdblayer.ErrAlreadyExists)
		}
		existingFuture := tr.Get(key)
		return func(ctx context.Context) error {
			if err := ctx.Err(); err != nil {
				return err
			}
			if existingFuture.MustGet() != nil {
				return fmt.Errorf("counter %w", fdblayer.ErrAlreadyExists)
			}
			// Marshal without mutating the caller's struct in-place.
			marshalTarget := entity
			if entity.Value != 0 || entity.MaxValue != 0 || entity.MinValue != 0 || entity.U64Max != 0 || entity.I32Min != 0 || entity.U32Add != 0 {
				marshalTarget = &Counter{
					Id: entity.Id,
				}
			}
			value, err := proto.Marshal(marshalTarget)
			if err != nil {
				return err
			}

			tr.Set(key, value)
			if entity.Value != 0 {
				fieldKey := dir.Pack(tuple.Tuple{CounterTypeID, fdblayer.FieldNamespace, entity.Id, 2})
				buf := make([]byte, 8)
				binary.LittleEndian.PutUint64(buf, uint64(entity.Value))
				tr.Add(fieldKey, buf)
			}
			{
				fieldKey := dir.Pack(tuple.Tuple{CounterTypeID, fdblayer.FieldNamespace, entity.Id, 3})
				buf := make([]byte, 8)
				binary.LittleEndian.PutUint64(buf, uint64(entity.MaxValue)^(1<<63))
				tr.Max(fieldKey, buf)
			}
			if entity.MinValue != 0 {
				fieldKey := dir.Pack(tuple.Tuple{CounterTypeID, fdblayer.FieldNamespace, entity.Id, 4})
				buf := make([]byte, 8)
				binary.LittleEndian.PutUint64(buf, uint64(entity.MinValue)^(1<<63))
				tr.Min(fieldKey, buf)
			}
			if entity.U64Max != 0 {
				fieldKey := dir.Pack(tuple.Tuple{CounterTypeID, fdblayer.FieldNamespace, entity.Id, 5})
				buf := make([]byte, 8)
				binary.LittleEndian.PutUint64(buf, uint64(entity.U64Max))
				tr.Max(fieldKey, buf)
			}
			if entity.I32Min != 0 {
				fieldKey := dir.Pack(tuple.Tuple{CounterTypeID, fdblayer.FieldNamespace, entity.Id, 6})
				buf := make([]byte, 8)
				binary.LittleEndian.PutUint64(buf, uint64(int64(entity.I32Min))^(1<<63))
				tr.Min(fieldKey, buf)
			}
			if entity.U32Add != 0 {
				fieldKey := dir.Pack(tuple.Tuple{CounterTypeID, fdblayer.FieldNamespace, entity.Id, 7})
				buf := make([]byte, 8)
				binary.LittleEndian.PutUint64(buf, uint64(entity.U32Add))
				tr.Add(fieldKey, buf)
			}
			return nil
		}, nil
	})
}

// Upsert returns a pipelined Mutation that inserts or updates a Counter entity, pre-reading the old record in parallel when needed.
func (r *counterRepository) Upsert(entity *Counter) fdblayer.Mutation {
	return fdblayer.MutationFunc(func(ctx context.Context, tx *fdblayer.Tx) (func(context.Context) error, error) {
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		tr := tx.Transaction()
		dir := tx.Dir()
		key := dir.Pack(tuple.Tuple{CounterTypeID, fdblayer.DataNamespace, entity.Id})
		oldFuture := tr.Get(key)
		return func(ctx context.Context) error {
			if err := ctx.Err(); err != nil {
				return err
			}
			isNewRecord := oldFuture.MustGet() == nil
			// Marshal without mutating the caller's struct in-place.
			marshalTarget := entity
			if entity.Value != 0 || entity.MaxValue != 0 || entity.MinValue != 0 || entity.U64Max != 0 || entity.I32Min != 0 || entity.U32Add != 0 {
				marshalTarget = &Counter{
					Id: entity.Id,
				}
			}
			value, err := proto.Marshal(marshalTarget)
			if err != nil {
				return err
			}

			tr.Set(key, value)
			if isNewRecord {
				if entity.Value != 0 {
					fieldKey := dir.Pack(tuple.Tuple{CounterTypeID, fdblayer.FieldNamespace, entity.Id, 2})
					buf := make([]byte, 8)
					binary.LittleEndian.PutUint64(buf, uint64(entity.Value))
					tr.Add(fieldKey, buf)
				}
				{
					fieldKey := dir.Pack(tuple.Tuple{CounterTypeID, fdblayer.FieldNamespace, entity.Id, 3})
					buf := make([]byte, 8)
					binary.LittleEndian.PutUint64(buf, uint64(entity.MaxValue)^(1<<63))
					tr.Max(fieldKey, buf)
				}
				if entity.MinValue != 0 {
					fieldKey := dir.Pack(tuple.Tuple{CounterTypeID, fdblayer.FieldNamespace, entity.Id, 4})
					buf := make([]byte, 8)
					binary.LittleEndian.PutUint64(buf, uint64(entity.MinValue)^(1<<63))
					tr.Min(fieldKey, buf)
				}
				if entity.U64Max != 0 {
					fieldKey := dir.Pack(tuple.Tuple{CounterTypeID, fdblayer.FieldNamespace, entity.Id, 5})
					buf := make([]byte, 8)
					binary.LittleEndian.PutUint64(buf, uint64(entity.U64Max))
					tr.Max(fieldKey, buf)
				}
				if entity.I32Min != 0 {
					fieldKey := dir.Pack(tuple.Tuple{CounterTypeID, fdblayer.FieldNamespace, entity.Id, 6})
					buf := make([]byte, 8)
					binary.LittleEndian.PutUint64(buf, uint64(int64(entity.I32Min))^(1<<63))
					tr.Min(fieldKey, buf)
				}
				if entity.U32Add != 0 {
					fieldKey := dir.Pack(tuple.Tuple{CounterTypeID, fdblayer.FieldNamespace, entity.Id, 7})
					buf := make([]byte, 8)
					binary.LittleEndian.PutUint64(buf, uint64(entity.U32Add))
					tr.Add(fieldKey, buf)
				}
			}
			return nil
		}, nil
	})
}

// Replace returns a blind write Mutation that writes a Counter entity without reading the existing record.
func (r *counterRepository) Replace(entity *Counter) fdblayer.Mutation {
	return fdblayer.MutationFunc(func(ctx context.Context, tx *fdblayer.Tx) (func(context.Context) error, error) {
		return func(ctx context.Context) error {
			if err := ctx.Err(); err != nil {
				return err
			}
			tr := tx.Transaction()
			dir := tx.Dir()
			key := dir.Pack(tuple.Tuple{CounterTypeID, fdblayer.DataNamespace, entity.Id})
			// Marshal without mutating the caller's struct in-place.
			marshalTarget := entity
			if entity.Value != 0 || entity.MaxValue != 0 || entity.MinValue != 0 || entity.U64Max != 0 || entity.I32Min != 0 || entity.U32Add != 0 {
				marshalTarget = &Counter{
					Id: entity.Id,
				}
			}
			value, err := proto.Marshal(marshalTarget)
			if err != nil {
				return err
			}

			tr.Set(key, value)
			if err := r.SetValue(ctx, tx, entity.Id, entity.Value); err != nil {
				return err
			}
			if err := r.SetMaxValue(ctx, tx, entity.Id, entity.MaxValue); err != nil {
				return err
			}
			if err := r.SetMinValue(ctx, tx, entity.Id, entity.MinValue); err != nil {
				return err
			}
			if err := r.SetU64Max(ctx, tx, entity.Id, entity.U64Max); err != nil {
				return err
			}
			if err := r.SetI32Min(ctx, tx, entity.Id, entity.I32Min); err != nil {
				return err
			}
			if err := r.SetU32Add(ctx, tx, entity.Id, entity.U32Add); err != nil {
				return err
			}
			return nil
		}, nil
	})
}

